import math


def radius_components(points, radius):
    if not isinstance(points, (list, tuple)):
        raise TypeError("points must be a list or tuple")
    if isinstance(radius, bool) or not isinstance(radius, (int, float)):
        raise TypeError("radius must be numeric")
    if not math.isfinite(radius) or radius < 0:
        raise ValueError("radius must be finite and non-negative")

    normalized = []
    for point in points:
        if not isinstance(point, (list, tuple)):
            raise TypeError("each point must be a list or tuple")
        if len(point) != 2:
            raise ValueError("each point must have two coordinates")
        pair = []
        for coordinate in point:
            if isinstance(coordinate, bool) or not isinstance(coordinate, (int, float)):
                raise TypeError("coordinates must be numeric")
            if not math.isfinite(coordinate):
                raise ValueError("coordinates must be finite")
            pair.append(coordinate)
        normalized.append(tuple(pair))

    count = len(normalized)
    labels = [-1] * count
    components = []
    radius_squared = radius * radius

    for start in range(count):
        if labels[start] != -1:
            continue
        label = len(components)
        labels[start] = label
        pending = [start]
        members = []
        cursor = 0
        while cursor < len(pending):
            current = pending[cursor]
            cursor += 1
            members.append(current)
            x1, y1 = normalized[current]
            for other in range(count):
                if labels[other] != -1:
                    continue
                x2, y2 = normalized[other]
                distance_squared = (x1 - x2) ** 2 + (y1 - y2) ** 2
                if distance_squared < radius_squared:
                    labels[other] = label
                    pending.append(other)
        components.append(tuple(sorted(members)))

    return {"labels": list(labels), "components": list(components)}

